def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def ranges(n, separators):
        result = []
        start = 0
        for i in separators:
            if start < i:
                result.append((start, i))
            start = i + 1
        if start < n:
            result.append((start, n))
        return result

    rs = ranges(h, sep_rows)
    cs = ranges(w, sep_cols)
    out = [row[:] for row in grid]

    blocks = []
    for ri, (r0, r1) in enumerate(rs):
        for ci, (c0, c1) in enumerate(cs):
            score = sum(grid[r][c] != bg for r in range(r0, r1) for c in range(c0, c1))
            blocks.append((score, ri, ci))

    _, tri, tci = max(blocks)
    tr0, tr1 = rs[tri]
    tc0, tc1 = cs[tci]
    template = [row[tc0:tc1] for row in grid[tr0:tr1]]

    for r0, r1 in rs:
        for c0, c1 in cs:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = template[(r - r0) % len(template)][(c - c0) % len(template[0])]
    return out
